import React, { useEffect, useRef, useState } from "react";
import pdf from "../../Assets/CV_DDV.pdf";
import usePageTitle from "../../usePageTitle";
import { Document, Page, pdfjs } from "react-pdf";
import "react-pdf/dist/esm/Page/AnnotationLayer.css";
pdfjs.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjs.version}/pdf.worker.min.js`;

// Positions and degrees as listed in CV_DDV.pdf, so the page reads without the PDF.
const experience = [
  {
    period: "2025 –",
    role: "Full-stack Protein Designer",
    place: "Computational Structural Biology Unit, Institut Pasteur, Paris",
  },
  {
    period: "2026",
    role: "Visiting Researcher in Protein Design",
    place: "DeGrado Lab, UCSF, San Francisco",
  },
  {
    period: "2019 – 2024",
    role: "Structural Biologist Focusing on Disordered Proteins",
    place: "Laboratoire des biomolécules, UMR 7203, Paris",
  },
];

const education = [
  { period: "PhD", role: "Integrative Structural Biology", place: "ENS – PSL University, Paris" },
  { period: "MSc", role: "Integrative Structural Biology", place: "Université Grenoble Alpes" },
  { period: "BSc", role: "Pharmacy", place: "University of Medicine and Pharmacy, Ho Chi Minh City" },
];

function Entries({ rows }) {
  return (
    <dl className="cv-entries">
      {rows.map((r) => (
        <div key={r.role + r.period}>
          <dt className="mono">{r.period}</dt>
          <dd>
            <strong>{r.role}</strong>
            <span>{r.place}</span>
          </dd>
        </div>
      ))}
    </dl>
  );
}

function ResumeNew() {
  usePageTitle("CV");
  const frameRef = useRef(null);
  const [width, setWidth] = useState(800);
  const [numPages, setNumPages] = useState(0);

  useEffect(() => {
    const el = frameRef.current;
    if (!el) return undefined;
    const update = () => setWidth(Math.min(900, el.clientWidth - 2 * parseFloat(getComputedStyle(el).paddingLeft)));
    update();
    window.addEventListener("resize", update);
    return () => window.removeEventListener("resize", update);
  }, []);

  return (
    <>
      <section className="hero" aria-labelledby="cv-title">
        <div className="wrap grid-12">
          <p className="hero-hello label">Curriculum vitae</p>
          <h1 className="hero-name" id="cv-title">
            CV
          </h1>
          <div className="cv-actions">
            <a className="button" href={pdf} download="Duy_Vu_CV.pdf">
              Download CV
            </a>
            <a className="arrow-link" href={pdf} target="_blank" rel="noopener noreferrer">
              Open in new tab
            </a>
          </div>
        </div>
      </section>

      <section className="section" aria-labelledby="cv-experience-label">
        <div className="wrap grid-12">
          <h2 className="section-label" id="cv-experience-label">
            <span className="label">Experience</span>
          </h2>
          <div className="col-main">
            <Entries rows={experience} />
          </div>
        </div>
      </section>

      <section className="section" aria-labelledby="cv-education-label">
        <div className="wrap grid-12">
          <h2 className="section-label" id="cv-education-label">
            <span className="label">Education</span>
          </h2>
          <div className="col-main">
            <Entries rows={education} />
          </div>
        </div>
      </section>

      <section className="section" aria-labelledby="cv-document-label">
        <div className="wrap grid-12">
          <h2 className="section-label" id="cv-document-label">
            <span className="label">Full document</span>
          </h2>
          <div className="cv-document" ref={frameRef}>
            <Document
              file={pdf}
              onLoadSuccess={({ numPages: n }) => setNumPages(n)}
              loading={<p className="cv-status">Loading CV…</p>}
              error={
                <p className="cv-status">
                  The CV could not be displayed here. Use Download CV above to open the PDF.
                </p>
              }
            >
              {Array.from({ length: numPages }, (_, i) => (
                <Page key={i} pageNumber={i + 1} width={width} renderTextLayer={false} />
              ))}
            </Document>
          </div>
        </div>
      </section>
    </>
  );
}

export default ResumeNew;
